// ============================================
// COMPONENT
// ============================================

interface EditFieldInfo {
  fieldName: string;
  fieldType: string;
  numberConfig?: NumberFormatConfig;
}

interface CreateFieldPanelProps {
  /** Position to render at (fixed, from + button rect) */
  position: { top: number; left: number };
  onClose: () => void;
  /** Called when a field type is selected. For now, just the label. */
  onSelectFieldType?: (fieldType: string) => void;
  /** Called when the user confirms field creation (name, UI type label, default value, optional number config). */
  onCreateField?: (name: string, type: string, defaultValue: string, numberConfig?: NumberFormatConfig) => void;
  /** When provided, opens directly in edit mode for the given field */
  editField?: EditFieldInfo;
  /** Called when saving in edit mode (name + optional number config) */
  onEditFieldSave?: (name: string, numberConfig?: NumberFormatConfig) => void;
  /** Existing field names in the table (for duplicate detection) */
  existingFieldNames?: string[];
  /** Base theme color for the automate icon */
  baseColor?: string;
}

// Only these field types are fully implemented
const enabledFieldTypes = new Set(["Single line text", "Number"]);

export function CreateFieldPanel({ position, onClose, onSelectFieldType, onCreateField, editField, onEditFieldSave, existingFieldNames, baseColor }: CreateFieldPanelProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedField, setSelectedField] = useState<{ label: string; icon: React.ReactNode } | null>(null);
  // "full" = initial picker (agents + standard), "typeSwitch" = shortened (standard only)
  const [pickerMode, setPickerMode] = useState<"full" | "typeSwitch">("full");
  const [showDiscardDialog, setShowDiscardDialog] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const editModeInitialized = useRef(false);

  // When in edit mode, immediately jump to the config panel for the right field type
  useEffect(() => {
    if (editField && !editModeInitialized.current) {
      editModeInitialized.current = true;
      const match = standardFieldItems.find((f) => f.label === editField.fieldType);
      if (match) {
        setSelectedField({ label: match.label, icon: match.icon });
      }
    }
  }, [editField]);

  // Focus input on mount (only when in picker mode)
  useEffect(() => {
    if (!selectedField) {
      setTimeout(() => inputRef.current?.focus(), 0);
    }
  }, [selectedField]);

  // Click-outside handler
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (panelRef.current && !panelRef.current.contains(event.target as Node)) {
        // Don't close if clicking inside a number-dropdown popup (rendered via portal)
        const target = event.target as HTMLElement;
        if (target.closest?.("[data-field-dropdown-popup]")) return;
        // Don't close if clicking inside the discard dialog
        if (target.closest?.("[data-discard-dialog]")) return;
        // If configuring a Number field (and NOT in edit mode), show discard confirmation instead of closing
        if (selectedField?.label === "Number" && !editField) {
          setShowDiscardDialog(true);
          return;
        }
        onClose();
      }
    }
    const t = setTimeout(() => document.addEventListener("mousedown", handleClickOutside), 10);
    return () => { clearTimeout(t); document.removeEventListener("mousedown", handleClickOutside); };
  }, [onClose, selectedField, editField]);

  // Escape key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        // If the discard dialog is showing, close it (go back to config)
        if (showDiscardDialog) {
          setShowDiscardDialog(false);
          return;
        }
        // If configuring a Number field (and NOT in edit mode), show discard confirmation
        if (selectedField?.label === "Number" && !editField) {
          setShowDiscardDialog(true);
          return;
        }
        onClose();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [onClose, selectedField, showDiscardDialog, editField]);

  const queryLower = searchQuery.toLowerCase().trim();

  // Filter field agents
  const filteredAgents = queryLower
    ? fieldAgentItems.filter((item) => item.label.toLowerCase().includes(queryLower))
    : fieldAgentItems;

  // Filter standard fields
  const filteredStandard = queryLower
    ? standardFieldItems.filter((item) => item.label.toLowerCase().includes(queryLower))
    : standardFieldItems;

  // Compute max-height: 8px from bottom of viewport
  const maxHeight = Math.max(300, window.innerHeight - position.top - 8);

  return (<>
    {createPortal(
    <div
      ref={panelRef}
      className={styles.createFieldPanel}
      style={{
        position: "fixed",
        zIndex: 99999,
        top: position.top,
        left: position.left,
        maxHeight: selectedField ? undefined : maxHeight,
        padding: selectedField ? 0 : 6,
        overflowY: selectedField ? "visible" : "auto",
      }}
      onClick={(e) => e.stopPropagation()}
    >
      {selectedField ? (
        /* === FIELD CONFIG VIEW === */
        <FieldConfigPanel
          fieldType={selectedField.label}
          fieldTypeIcon={selectedField.icon}
          onBack={() => {
            setPickerMode("typeSwitch");
            setSelectedField(null);
            setSearchQuery("");
          }}
          onClose={onClose}
          onCreateField={onCreateField}
          isEditMode={!!editField}
          initialFieldName={editField?.fieldName}
          initialNumberConfig={editField?.numberConfig}
          onEditFieldSave={onEditFieldSave}
          existingFieldNames={existingFieldNames}
          baseColor={baseColor}
        />
      ) : (
        /* === FIELD TYPE PICKER VIEW === */
        <>
          {/* === Sticky search header === */}
          <div className={styles.searchHeader}>
            <div className={styles.searchRow}>
              <div className={styles.searchBox}>
                <SearchIcon />
                <input
                  ref={inputRef}
                  className={styles.searchInput}
                  type="text"
                  placeholder="Find a field type"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <span className={styles.questionIcon}>
                <QuestionIcon />
              </span>
            </div>
          </div>

          {/* === Divider === */}
          <hr className={`${styles.divider} ${pickerMode === "typeSwitch" ? styles.dividerSticky : ""}`} />

          {/* === Scrollable content === */}
          <div className={styles.scrollableContent}>
            {/* Field agents section (only in full mode) */}
            {pickerMode === "full" && filteredAgents.length > 0 && (
              <>
                <p className={styles.sectionLabel}>Field agents</p>
                <div className={styles.agentsGrid}>
                  {filteredAgents.map((agent, idx) => {
                    // Top 6 agents get colored hover, last 2 get standard grey
                    const coloredHover = idx < 6;
                    return (
                      <div
                        key={agent.label}
                        className={styles.agentItem}
                        style={
                          coloredHover
                            ? ({ "--hover-bg": `${agent.color}14` } as React.CSSProperties)
                            : undefined
                        }
                        onClick={() => {
                          setSelectedField({ label: agent.label, icon: agent.icon });
                          onSelectFieldType?.(agent.label);
                        }}
                      >
                        <span className={styles.agentItemIcon} style={{ color: agent.color }}>
                          {agent.icon}
                        </span>
                        <span className={styles.agentItemText}>{agent.label}</span>
                      </div>
                    );
                  })}
                </div>
              </>
            )}

            {/* Divider between agents and standard fields (only in full mode) */}
            {pickerMode === "full" && filteredAgents.length > 0 && filteredStandard.length > 0 && (
              <hr className={styles.dividerThin} />
            )}

            {/* Standard fields section */}
            {filteredStandard.length > 0 && (
              <>
                {pickerMode === "full" && (
                  <p className={styles.sectionLabel}>Standard fields</p>
                )}
                {filteredStandard.map((field) => {
                  const disabled = !enabledFieldTypes.has(field.label);
                  return (
                    <div
                      key={field.label}
                      className={`${styles.standardItem} ${disabled ? styles.disabledItem : ""}`}
                      onClick={
                        disabled
                          ? undefined
                          : () => {
                              setSelectedField({ label: field.label, icon: field.icon });
                              onSelectFieldType?.(field.label);
                            }
                      }
                    >
                      <span className={styles.standardItemIcon}>
                        {field.icon}
                      </span>
                      <span className={styles.standardItemTextWrapper}>
                        <span className={styles.standardItemText}>{field.label}</span>
                        {field.hasChevron && (
                          <span className={styles.standardItemChevron}>
                            <ChevronRight />
                          </span>
                        )}
                      </span>
                    </div>
                  );
                })}
              </>
            )}

            {/* Empty state */}
            {(pickerMode === "full" ? filteredAgents.length === 0 && filteredStandard.length === 0 : filteredStandard.length === 0) && (
              <p className={styles.emptyState}>No matching field types</p>
            )}
          </div>
        </>
      )}
    </div>,
    document.body,
  )}

  {/* === Discard confirmation dialog === */}
  {showDiscardDialog && createPortal(
    <div
      className={styles.discardOverlay}
      data-discard-dialog="true"
      onMouseDown={(e) => {
        // Clicking the backdrop (outside the dialog box) cancels the dialog
        if (e.target === e.currentTarget) {
          setShowDiscardDialog(false);
        }
      }}
    >
      <div className={styles.discardDialog}>
        <p className={styles.discardTitle}>Discard your new field?</p>
        <div className={styles.discardActions}>
          <button
            type="button"
            className={styles.discardCancelBtn}
            onClick={() => setShowDiscardDialog(false)}
          >
            Cancel
          </button>
          <button
            type="button"
            className={styles.discardConfirmBtn}
            onClick={onClose}
          >
            Discard
          </button>
        </div>
      </div>
    </div>,
    document.body,
  )}
  </>);
}
